UPDATE public.grammar_rules SET content = '{"points":["0-12: memorize individually (null, eins, zwei... zwölf)","13-19: number + zehn (dreizehn, vierzehn...). Exception: sechzehn, siebzehn","20-90: number + zig (zwanzig, dreißig, vierzig...)","21-99: Ones + und + Tens (backwards!). 45 = fünfundvierzig","All compound numbers are written as one word","30 = dreißig (with ß, not z). 60 = sechzig. 70 = siebzig.","100+ are one word too: zweihundert, dreitausend, zweitausendsechsundzwanzig. ''ein'' is optional for 100/1000 (hundert = einhundert, tausend = eintausend).","Prices: Euro first, then Cent, no ''und'' — zwei Euro fünfzig (2,50 €), neunundneunzig Cent (0,99 €). Euro has no plural -s: zwölf Euro.","Ordinal numbers: 1.-19. add -te (erste, dritte, siebte, achte are irregular), 20.+ always add -ste; use -e after der/die/das, -en after im/am."]}'::jsonb
WHERE id = '125e153e-258b-4337-bbad-b6b20d1997bd'::uuid AND content = '{"points":["0-12: memorize individually (null, eins, zwei... zwölf)","13-19: number + zehn (dreizehn, vierzehn...). Exception: sechzehn, siebzehn","20-90: number + zig (zwanzig, dreißig, vierzig...)","21-99: Ones + und + Tens (backwards!). 45 = fünfundvierzig","All compound numbers are written as one word","30 = dreißig (with ß, not z). 60 = sechzig. 70 = siebzig."]}'::jsonb;

-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f67c3da1-1fcb-57a8-b5e4-a5e3abe53109'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 'table', 'Hundreds and Thousands', 'Hunderter und Tausend', '{"type":"case_table","headers":["Zahl","Deutsch","Muster"],"rows":[["100","hundert","hundert (ohne ''ein'') — ''einhundert'' ist auch richtig"],["101","hunderteins","hundert + eins, ein Wort"],["200","zweihundert","zwei + hundert, ein Wort"],["300","dreihundert","drei + hundert, ein Wort"],["999","neunhundertneunundneunzig","neun + hundert + (neunundneunzig)"],["1000","tausend","tausend (ohne ''ein'') — ''eintausend'' ist auch richtig"],["2026","zweitausendsechsundzwanzig","zwei + tausend + (sechsundzwanzig) — eine Jahreszahl"]],"highlight_row":-1,"description_de":"Hunderter und Tausender werden wie die Zehnerzahlen als EIN Wort geschrieben: zweihundert, nicht zwei hundert. Bei 100 und 1000 ist ''ein'' optional: hundert = einhundert, tausend = eintausend, beide sind richtig.","description_en":"Hundreds and thousands are written as ONE word, just like the tens: zweihundert (two hundred), not zwei hundert. For 100 and 1000, ''ein'' is optional: hundert = einhundert, tausend = eintausend — both are correct."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"zwei hundert","correct":"zweihundert","explanation_de":"Hunderterzahlen sind ein Wort, kein Leerzeichen.","explanation_en":"Hundred numbers are one word — no space between the parts."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f67c3da1-1fcb-57a8-b5e4-a5e3abe53109'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'b111c788-cfea-5d71-a2ba-ff7b9540c2d6'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 'table', 'Prices', 'Preise', '{"type":"case_table","headers":["Preis","Deutsch","Hinweis"],"rows":[["2,50 €","zwei Euro fünfzig","Euro zuerst, dann Cent — kein ''und'' dazwischen"],["0,99 €","neunundneunzig Cent","unter 1 € nennt man nur die Cent"],["12,00 €","zwölf Euro","ganze Euro ohne Cent-Angabe"]],"highlight_row":-1,"description_de":"Preise: Euro zuerst, dann Cent, ohne ''und'' (zwei Euro fünfzig, nicht zwei Euro und fünfzig — ''zwei Euro fünfzig Cent'' ist auch richtig). Euro hat keine Plural-Endung nach Zahlen: zwölf Euro, nicht zwölf Euros. Frage: Was kostet das Brot? — Antwort des Verkäufers: Das macht zwölf Euro.","description_en":"Prices: euros first, then cents, with no ''und'' between them (zwei Euro fünfzig, not zwei Euro und fünfzig — ''zwei Euro fünfzig Cent'' is also correct). Euro takes no plural -s after a number: zwölf Euro, not zwölf Euros. Question: Was kostet das Brot? (What does the bread cost?) — Shop answer: Das macht zwölf Euro. (That comes to twelve euros.)"}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"zwei Euro und fünfzig","correct":"zwei Euro fünfzig","explanation_de":"Zwischen Euro und Cent steht kein ''und''.","explanation_en":"There is no ''und'' between the euros and the cents."},{"wrong":"zwölf Euros","correct":"zwölf Euro","explanation_de":"Euro bekommt nach einer Zahl kein Plural-s.","explanation_en":"Euro takes no plural -s after a number."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'b111c788-cfea-5d71-a2ba-ff7b9540c2d6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1c3cfcbf-f863-5ce1-a056-01268987a9dc'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 'table', 'Ordinal Numbers', 'Ordinalzahlen', '{"type":"case_table","headers":["Zahl","Ordinalzahl","Beispiel"],"rows":[["1.","erste","im ersten Stock (unregelmäßig!)"],["2.","zweite","die zweite Straße links"],["3.","dritte","die dritte Tür (unregelmäßig!)"],["7.","siebte","der siebte Tag (unregelmäßig!)"],["8.","achte","die achte Woche (unregelmäßig!)"],["10.","zehnte","das zehnte Jahr"],["19.","neunzehnte","letzte Zahl mit -te"],["20.","zwanzigste","ab 20 immer -ste"],["21.","einundzwanzigste","einundzwanzig + ste"]],"highlight_row":-1,"description_de":"1.–19. bekommen -te (aber erste, dritte, siebte und achte sind unregelmäßig!). Ab 20 immer -ste. Die Schreibweise ''1.'' bedeutet ''erste''. Endung: nach der/die/das -e (die dritte Straße), nach im/am -en (im ersten Stock, am fünften Mai). Für Datumsangaben siehe das Thema ''Uhrzeit, Wochentage und Datum''.","description_en":"1st–19th add -te (but erste, dritte, siebte and achte are irregular!). From 20th on, always add -ste. The notation ''1.'' means ''erste''. Ending: after der/die/das use -e (die dritte Straße), after im/am use -en (im ersten Stock, am fünften Mai). For dates, see the topic ''Telling the time, weekdays and dates''."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"dreite","correct":"dritte","explanation_de":"3. ist unregelmäßig: dritte, nicht dreite.","explanation_en":"3rd is irregular: dritte, not dreite."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1c3cfcbf-f863-5ce1-a056-01268987a9dc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4dbd3403-9d91-57a2-8de4-55e19c8150be'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 'tip', 'Phone Numbers and Postal Codes', 'Telefonnummern und Postleitzahlen', '{"content_de":"Telefonnummern und Postleitzahlen liest man Ziffer für Ziffer: 06923 = null-sechs-neun-zwei-drei. Manchmal liest man auch in Paaren: 12-34 = zwölf-vierunddreißig. Das brauchst du für Formulare.","content_en":"Phone numbers and postal codes (Postleitzahlen) are read digit by digit: 06923 = null-sechs-neun-zwei-drei. Sometimes pairs are used instead: 12-34 = zwölf-vierunddreißig. You need this for filling out forms (Formulare)."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4dbd3403-9d91-57a2-8de4-55e19c8150be'::uuid);

