SELECT 'fb78281e-be58-591c-913a-e071f141dc0b'::uuid, 'db0bcf43-b8ed-4a59-b545-89d93dc745b0'::uuid, 5, 'fill_blank', 'Das Mädchen ist neu. ___ ist nett.', 'The girl is new (here). ___ is nice. (pronoun for das Mädchen — even though a girl is female, das Mädchen is neuter)', NULL, 'Es', '["Es"]'::jsonb, 'Das Mädchen is grammatically neuter (the -chen ending), so it becomes es, not sie.', 'Das Mädchen ist grammatisch neutral (Endung -chen), deshalb es, nicht sie.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Grammar beats biology: -chen nouns always take es, regardless of meaning.', 'Grammatik schlägt Bedeutung: -chen-Nomen nehmen immer es.', NULL
