INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '19f1aa27-7634-5599-8a61-8f69e259f6d4'::uuid, 'a0441d44-095f-421f-845a-cc5897c7a1b2'::uuid, 5, 'fill_blank', 'Das ___ Kaffee.', 'That ___ coffee. (verb: sein, das)', NULL, 'ist', '["ist"]'::jsonb, 'Das pairs with ist, just like er/sie/es.', 'Das steht mit ist, genau wie er/sie/es.', NULL, 15, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Das is grammatically third person, so it uses ist.', 'Das ist grammatisch 3. Person, deshalb ist.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '19f1aa27-7634-5599-8a61-8f69e259f6d4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dae9ebf1-4492-563c-8aa0-142a40f8197f'::uuid, 'a0441d44-095f-421f-845a-cc5897c7a1b2'::uuid, 5, 'fill_blank', '___ Sie fertig?', '___ you ready? (formal question, verb: sein)', NULL, 'Sind', '["Sind","sind"]'::jsonb, 'In a formal question, the verb sind comes first.', 'In einer formellen Frage steht sind zuerst.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Yes/no questions put the sein-form before the subject.', 'Ja/Nein-Fragen stellen die sein-Form vor das Subjekt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dae9ebf1-4492-563c-8aa0-142a40f8197f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4ecbc321-a7fa-57e4-8d21-285cd34986e4'::uuid, 'a0441d44-095f-421f-845a-cc5897c7a1b2'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / Lehrer]', 'Write the sentence: [we / teachers] (verb: sein, wir)', NULL, 'Wir sind Lehrer.', '["Wir sind Lehrer.","Wir sind Lehrer"]'::jsonb, 'Wir takes sind — sein is irregular, so its wir-form is not built from the infinitive like regular verbs.', 'Wir nimmt sind — sein ist unregelmäßig, die wir-Form entsteht nicht wie bei regelmäßigen Verben aus dem Infinitiv.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sein’s forms must be memorized individually; they don’t follow the regular pattern.', 'Die Formen von sein müssen einzeln gelernt werden; sie folgen nicht dem regelmäßigen Muster.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4ecbc321-a7fa-57e4-8d21-285cd34986e4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '459b2960-6610-57b4-b4f9-631bf6eeed01'::uuid, 'a0441d44-095f-421f-845a-cc5897c7a1b2'::uuid, 5, 'fill_blank', 'Sie ___ meine Schwester.', 'She ___ my sister. (verb: sein, sie = she, singular)', NULL, 'ist', '["ist"]'::jsonb, 'Singular sie (she) pairs with ist, like er and das.', 'Singular-sie (she) steht mit ist, wie er und das.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sie as ‘she’ is third person singular, so it takes ist.', 'Sie als ‘she’ ist 3. Person Singular, deshalb ist.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '459b2960-6610-57b4-b4f9-631bf6eeed01'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1a4533bd-b414-575d-a652-ff6fbe7adfd3'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich trinke ___ Kaffee. (der Kaffee)', 'I drink the coffee. (accusative direct object, definite article)', NULL, 'den', '["den"]'::jsonb, 'Kaffee is masculine and the direct object, so der becomes den.', 'Kaffee ist maskulin und direktes Objekt, deshalb wird der zu den.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wen trinke ich? Den Kaffee. Masculine accusative: der → den.', 'Wen trinke ich? Den Kaffee. Maskulin Akkusativ: der → den.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1a4533bd-b414-575d-a652-ff6fbe7adfd3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e8300998-0168-55ef-9ba9-db97acb1be90'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Sie kauft ___ Kuchen. (ein Kuchen)', 'She buys a cake. (accusative direct object, indefinite article)', NULL, 'einen', '["einen"]'::jsonb, 'Kuchen is masculine and the direct object, so ein becomes einen.', 'Kuchen ist maskulin und direktes Objekt, deshalb wird ein zu einen.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Was kauft sie? Einen Kuchen. Masculine accusative: ein → einen.', 'Was kauft sie? Einen Kuchen. Maskulin Akkusativ: ein → einen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e8300998-0168-55ef-9ba9-db97acb1be90'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a84d1592-fb36-5d2c-b7ee-8588ac47b98d'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich habe ___ Schlüssel. (kein Schlüssel)', 'I have no key. (accusative direct object, negated)', NULL, 'keinen', '["keinen"]'::jsonb, 'Schlüssel is masculine and negated, so kein becomes keinen.', 'Schlüssel ist maskulin und verneint, deshalb wird kein zu keinen.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative negation: kein → keinen Schlüssel.', 'Maskuline Akkusativ-Verneinung: kein → keinen Schlüssel.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a84d1592-fb36-5d2c-b7ee-8588ac47b98d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '007a88c0-9b75-57d3-9ea7-62f363ce3c36'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich besuche ___ Vater. (mein Vater)', 'I am visiting my father. (accusative direct object, possessive)', NULL, 'meinen', '["meinen"]'::jsonb, 'Vater is masculine and the direct object, so mein becomes meinen.', 'Vater ist maskulin und direktes Objekt, deshalb wird mein zu meinen.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wen besuche ich? Meinen Vater. Masculine accusative: mein → meinen.', 'Wen besuche ich? Meinen Vater. Maskulin Akkusativ: mein → meinen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '007a88c0-9b75-57d3-9ea7-62f363ce3c36'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f582088a-97c2-5619-b502-417884287612'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich lese ___ Buch. (das Buch)', 'I read the book. (accusative direct object, neuter — no change from nominative)', NULL, 'das', '["das"]'::jsonb, 'Buch is neuter, so the accusative article stays das, unlike masculine der → den.', 'Buch ist Neutrum, deshalb bleibt der Akkusativartikel das, anders als maskulin der → den.', NULL, 20, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only masculine changes in the accusative; neuter das stays das.', 'Nur Maskulin ändert sich im Akkusativ; neutrales das bleibt das.', NULL
