INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8e481c5f-9052-529b-9af0-addaf53c66f8'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich rufe ___ Freund an. (mein Freund)', 'I am calling my friend. (accusative object, separable verb anrufen)', NULL, 'meinen', '["meinen"]'::jsonb, 'Freund is masculine and the direct object of anrufen, so mein becomes meinen.', 'Freund ist maskulin und direktes Objekt von anrufen, deshalb wird mein zu meinen.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wen rufe ich an? Meinen Freund. Masculine accusative: mein → meinen.', 'Wen rufe ich an? Meinen Freund. Maskulin Akkusativ: mein → meinen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8e481c5f-9052-529b-9af0-addaf53c66f8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c8ba2936-e494-510a-b33e-75feca9f2678'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / einen / Onkel / haben]', 'Write the sentence: I have an uncle. (accusative direct object, indefinite article)', NULL, 'Ich habe einen Onkel.', '["Ich habe einen Onkel.","Ich habe einen Onkel","Einen Onkel habe ich.","Einen Onkel habe ich"]'::jsonb, 'Onkel is masculine and the direct object of haben, so ein becomes einen.', 'Onkel ist maskulin und direktes Objekt von haben, deshalb wird ein zu einen.', NULL, 22, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Was habe ich? Einen Onkel. Masculine accusative: ein → einen. Fronting the object (Einen Onkel habe ich.) for emphasis is also correct — the case does not change.', 'Was habe ich? Einen Onkel. Maskulin Akkusativ: ein → einen. Auch mit vorangestelltem Objekt (Einen Onkel habe ich.) bleibt der Fall gleich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c8ba2936-e494-510a-b33e-75feca9f2678'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'da81d5c0-487f-594d-8756-e6ab62677884'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Er sucht ___ Stift. (der Stift)', 'He is looking for the pen. (accusative direct object, definite article)', NULL, 'den', '["den"]'::jsonb, 'Stift is masculine and the direct object, so der becomes den.', 'Stift ist maskulin und direktes Objekt, deshalb wird der zu den.', NULL, 23, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Was sucht er? Den Stift. Masculine accusative: der → den.', 'Was sucht er? Den Stift. Maskulin Akkusativ: der → den.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'da81d5c0-487f-594d-8756-e6ab62677884'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2392f776-9fcc-5cf1-8c10-b5c3cedbdd68'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'fill_blank', 'Ich sehe ___ Lampe. (die Lampe)', 'I see the lamp. (accusative direct object, feminine — no change from nominative)', NULL, 'die', '["die"]'::jsonb, 'Lampe is feminine, so the accusative article stays die, unlike masculine der → den.', 'Lampe ist feminin, deshalb bleibt der Akkusativartikel die, anders als maskulin der → den.', NULL, 24, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only masculine changes in the accusative; feminine die stays die.', 'Nur Maskulin ändert sich im Akkusativ; feminines die bleibt die.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2392f776-9fcc-5cf1-8c10-b5c3cedbdd68'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2b88afc2-b8cb-50fc-9a54-0953988b498b'::uuid, '748b6d47-2ad5-41fa-927c-c7449675a07b'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du / kein / Hund / haben]', 'Write the sentence: You have no dog. (kein must be inflected to keinen — masculine accusative negation)', NULL, 'Du hast keinen Hund.', '["Du hast keinen Hund.","Du hast keinen Hund"]'::jsonb, 'Hund is masculine, so the given kein must be inflected to keinen in the accusative.', 'Hund ist maskulin, deshalb muss das gegebene kein im Akkusativ zu keinen werden.', NULL, 25, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative negation needs the -en ending: kein → keinen Hund.', 'Maskuline Akkusativ-Verneinung braucht die Endung -en: kein → keinen Hund.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2b88afc2-b8cb-50fc-9a54-0953988b498b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6d0a5335-94cd-5d2d-b844-0343b6171c63'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [morgen / ich / aufstehen / früh]', 'Write the sentence: Tomorrow I am getting up early. (time-first inversion, separable verb aufstehen)', NULL, 'Morgen stehe ich früh auf.', '["Morgen stehe ich früh auf.","Morgen stehe ich früh auf"]'::jsonb, 'Time (morgen) takes position 1, so the verb stehe moves to position 2 and ich follows.', 'Zeit (morgen) steht auf Position 1, das Verb stehe rückt auf Position 2, dann ich.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'V2 rule: morgen (pos 1) + stehe (pos 2) + ich (pos 3) + früh + auf (end).', 'V2-Regel: morgen (Pos 1) + stehe (Pos 2) + ich (Pos 3) + früh + auf (Ende).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6d0a5335-94cd-5d2d-b844-0343b6171c63'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fcb99966-b8d2-5eb1-a466-f6c31cfa771e'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [am Montag / wir / einkaufen]', 'Write the sentence: On Monday we are going shopping. (time-first inversion, separable verb einkaufen)', NULL, 'Am Montag kaufen wir ein.', '["Am Montag kaufen wir ein.","Am Montag kaufen wir ein"]'::jsonb, 'Am Montag is one time expression in position 1, so kaufen moves to position 2.', 'Am Montag ist eine Zeitangabe auf Position 1, deshalb rückt kaufen auf Position 2.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first inversion: Am Montag (pos 1) + kaufen (pos 2) + wir (pos 3) + ein (end).', 'Zeit zuerst: Am Montag (Pos 1) + kaufen (Pos 2) + wir (Pos 3) + ein (Ende).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fcb99966-b8d2-5eb1-a466-f6c31cfa771e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '20fdea30-db58-5380-b2e5-c2a3eff7f6c7'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [heute / meine Mutter / kochen / das Essen]', 'Write the sentence: Today my mother is cooking the food. (time-first inversion)', NULL, 'Heute kocht meine Mutter das Essen.', '["Heute kocht meine Mutter das Essen.","Heute kocht meine Mutter das Essen"]'::jsonb, 'Heute is in position 1, so kocht moves to position 2 and the subject follows.', 'Heute steht auf Position 1, deshalb rückt kocht auf Position 2, dann das Subjekt.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first: Heute (pos 1) + kocht (pos 2) + meine Mutter (pos 3) + das Essen.', 'Zeit zuerst: Heute (Pos 1) + kocht (Pos 2) + meine Mutter (Pos 3) + das Essen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '20fdea30-db58-5380-b2e5-c2a3eff7f6c7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7b3f950f-b3dd-5e01-9980-6e316bb70519'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [am Dienstag / ich / Gitarre / spielen]', 'Write the sentence: On Tuesday I play guitar. (time-first inversion, plain verb)', NULL, 'Am Dienstag spiele ich Gitarre.', '["Am Dienstag spiele ich Gitarre.","Am Dienstag spiele ich Gitarre"]'::jsonb, 'Am Dienstag is position 1, so spiele moves to position 2 and ich follows.', 'Am Dienstag steht auf Position 1, deshalb rückt spiele auf Position 2, dann ich.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first: Am Dienstag (pos 1) + spiele (pos 2) + ich (pos 3) + Gitarre.', 'Zeit zuerst: Am Dienstag (Pos 1) + spiele (Pos 2) + ich (Pos 3) + Gitarre.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7b3f950f-b3dd-5e01-9980-6e316bb70519'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '87cbcd4f-ee7f-5064-8a10-5dfef834d9d2'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [um acht Uhr / wir / anfangen]', 'Write the sentence: We start at eight o''clock. (time-first inversion, separable verb anfangen, wir-form so no stem change)', NULL, 'Um acht Uhr fangen wir an.', '["Um acht Uhr fangen wir an.","Um acht Uhr fangen wir an"]'::jsonb, 'Um acht Uhr is position 1, so fangen moves to position 2 and wir follows.', 'Um acht Uhr steht auf Position 1, deshalb rückt fangen auf Position 2, dann wir.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first: Um acht Uhr (pos 1) + fangen (pos 2) + wir (pos 3) + an (end).', 'Zeit zuerst: Um acht Uhr (Pos 1) + fangen (Pos 2) + wir (Pos 3) + an (Ende).', NULL
