SELECT '68174fed-dcd5-52e1-93aa-a3efccab10f0'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [am Samstag / wir / nach Berlin / fliegen]', 'Write the sentence: On Saturday we are flying to Berlin. (time-first inversion, plain verb)', NULL, 'Am Samstag fliegen wir nach Berlin.', '["Am Samstag fliegen wir nach Berlin.","Am Samstag fliegen wir nach Berlin"]'::jsonb, 'Am Samstag is position 1, so fliegen moves to position 2 and wir follows.', 'Am Samstag steht auf Position 1, deshalb rückt fliegen auf Position 2, dann wir.', NULL, 21, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first: Am Samstag (pos 1) + fliegen (pos 2) + wir (pos 3) + nach Berlin.', 'Zeit zuerst: Am Samstag (Pos 1) + fliegen (Pos 2) + wir (Pos 3) + nach Berlin.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '68174fed-dcd5-52e1-93aa-a3efccab10f0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '471c8256-d11e-5e79-b2b2-0e1a2066c875'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [in Hamburg / mein Bruder / arbeiten]', 'Write the sentence: My brother works in Hamburg. Start with ''in Hamburg''. (place-first inversion)', NULL, 'In Hamburg arbeitet mein Bruder.', '["In Hamburg arbeitet mein Bruder.","In Hamburg arbeitet mein Bruder"]'::jsonb, 'The cue puts in Hamburg first, so arbeitet moves to position 2 and the subject follows.', 'Der Hinweis stellt in Hamburg an erste Stelle, deshalb rückt arbeitet auf Position 2, dann das Subjekt.', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Place-first: in Hamburg (pos 1, from the cue) + arbeitet (pos 2) + mein Bruder (pos 3).', 'Ort zuerst: in Hamburg (Pos 1, laut Hinweis) + arbeitet (Pos 2) + mein Bruder (Pos 3).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '471c8256-d11e-5e79-b2b2-0e1a2066c875'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '686d81f5-816b-53fc-b84e-2ea6c5aa237a'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'sentence_building', 'Schreib den Satz: [Fußball / wir / am Wochenende / spielen]', 'Write the sentence: We play football on the weekend. Start with ''Fußball''. (object-first, for emphasis)', NULL, 'Fußball spielen wir am Wochenende.', '["Fußball spielen wir am Wochenende.","Fußball spielen wir am Wochenende"]'::jsonb, 'The cue puts Fußball first for emphasis, so spielen moves to position 2 and wir follows.', 'Der Hinweis stellt Fußball zur Betonung an erste Stelle, deshalb rückt spielen auf Position 2, dann wir.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Object-first: Fußball (pos 1, from the cue) + spielen (pos 2) + wir (pos 3) + am Wochenende.', 'Objekt zuerst: Fußball (Pos 1, laut Hinweis) + spielen (Pos 2) + wir (Pos 3) + am Wochenende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '686d81f5-816b-53fc-b84e-2ea6c5aa237a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5223d628-e272-56f3-888a-d9ac6d33fe18'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'fill_blank', 'Am Freitag ___ meine Eltern nicht zu Hause. (sein)', 'On Friday my parents are not home. (time-first inversion, verb sein, plural)', NULL, 'sind', '["sind"]'::jsonb, 'Am Freitag is position 1, so sind (the plural form of sein) moves to position 2.', 'Am Freitag steht auf Position 1, deshalb rückt sind (Pluralform von sein) auf Position 2.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first: Am Freitag (pos 1) + sind (pos 2) + meine Eltern (pos 3) + nicht zu Hause.', 'Zeit zuerst: Am Freitag (Pos 1) + sind (Pos 2) + meine Eltern (Pos 3) + nicht zu Hause.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5223d628-e272-56f3-888a-d9ac6d33fe18'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '49857a1b-856f-5f16-a229-01eb95d8e781'::uuid, '2e4ad310-cda8-4076-a9ca-13baca1a5f20'::uuid, 5, 'fill_blank', 'Am Abend ___ ich Musik. (hören)', 'In the evening I listen to music. (time-first inversion, verb hören)', NULL, 'höre', '["höre"]'::jsonb, 'Am Abend is position 1, so the verb höre must come right after it.', 'Am Abend steht auf Position 1, deshalb kommt das Verb höre direkt danach.', NULL, 25, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'V2 rule: Am Abend (pos 1) + höre (pos 2) + ich (pos 3).', 'V2-Regel: Am Abend (Pos 1) + höre (Pos 2) + ich (Pos 3).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '49857a1b-856f-5f16-a229-01eb95d8e781'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '07cfcdf8-bdb8-5a5b-a3a4-6f54226b8982'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / heute / nicht / können / arbeiten]', 'Write the sentence: I can''t work today. (modal kann in position 2, infinitive at the end)', NULL, 'Ich kann heute nicht arbeiten.', '["Ich kann heute nicht arbeiten.","Ich kann heute nicht arbeiten","Heute kann ich nicht arbeiten.","Heute kann ich nicht arbeiten"]'::jsonb, 'kann is the conjugated modal in position 2; arbeiten (infinitive) goes to the end.', 'kann ist das konjugierte Modalverb auf Position 2; arbeiten (Infinitiv) steht am Ende.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Ich + kann (pos 2) + heute nicht + arbeiten (end, infinitive). Fronting heute instead (Heute kann ich nicht arbeiten.) is equally correct — kann still holds position 2.', 'Satzklammer: Ich + kann (Pos 2) + heute nicht + arbeiten (Ende, Infinitiv). Auch mit heute zuerst (Heute kann ich nicht arbeiten.) bleibt kann auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '07cfcdf8-bdb8-5a5b-a3a4-6f54226b8982'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '02f3c1af-470a-5019-9539-2dfbc5f6b0d2'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / am Sonntag / wollen / Fußball / spielen]', 'Write the sentence: We want to play football on Sunday. (modal wollen, infinitive at the end)', NULL, 'Wir wollen am Sonntag Fußball spielen.', '["Wir wollen am Sonntag Fußball spielen.","Wir wollen am Sonntag Fußball spielen","Am Sonntag wollen wir Fußball spielen.","Am Sonntag wollen wir Fußball spielen"]'::jsonb, 'wollen is the conjugated modal in position 2; spielen (infinitive) goes to the end.', 'wollen ist das konjugierte Modalverb auf Position 2; spielen (Infinitiv) steht am Ende.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Wir + wollen (pos 2) + am Sonntag Fußball + spielen (end, infinitive). Fronting am Sonntag instead is equally correct — wollen still holds position 2.', 'Satzklammer: Wir + wollen (Pos 2) + am Sonntag Fußball + spielen (Ende, Infinitiv). Auch mit am Sonntag zuerst bleibt wollen auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '02f3c1af-470a-5019-9539-2dfbc5f6b0d2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a00fa718-37f9-561e-871e-15fc3d5408e8'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du / heute / müssen / arbeiten]', 'Write the sentence: You have to work today. (modal musst, infinitive at the end)', NULL, 'Du musst heute arbeiten.', '["Du musst heute arbeiten.","Du musst heute arbeiten","Heute musst du arbeiten.","Heute musst du arbeiten"]'::jsonb, 'musst is the conjugated modal in position 2; arbeiten (infinitive) goes to the end.', 'musst ist das konjugierte Modalverb auf Position 2; arbeiten (Infinitiv) steht am Ende.', NULL, 18, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Du + musst (pos 2) + heute + arbeiten (end, infinitive). Fronting heute instead (Heute musst du arbeiten.) is equally correct — musst still holds position 2.', 'Satzklammer: Du + musst (Pos 2) + heute + arbeiten (Ende, Infinitiv). Auch mit heute zuerst bleibt musst auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a00fa718-37f9-561e-871e-15fc3d5408e8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c6e6c6b4-bf05-5ff5-bd3e-be2f79ab1593'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ihr / hier / dürfen / nicht / rauchen]', 'Write the sentence: You (pl.) may not smoke here. (modal dürft, infinitive at the end)', NULL, 'Ihr dürft hier nicht rauchen.', '["Ihr dürft hier nicht rauchen.","Ihr dürft hier nicht rauchen","Hier dürft ihr nicht rauchen.","Hier dürft ihr nicht rauchen"]'::jsonb, 'dürft is the conjugated modal in position 2; rauchen (infinitive) goes to the end.', 'dürft ist das konjugierte Modalverb auf Position 2; rauchen (Infinitiv) steht am Ende.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Ihr + dürft (pos 2) + hier nicht + rauchen (end, infinitive). Fronting hier instead (Hier dürft ihr nicht rauchen.) is equally correct — dürft still holds position 2.', 'Satzklammer: Ihr + dürft (Pos 2) + hier nicht + rauchen (Ende, Infinitiv). Auch mit hier zuerst bleibt dürft auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c6e6c6b4-bf05-5ff5-bd3e-be2f79ab1593'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef3c3e7a-c001-5105-be64-7500ac2d9e29'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / einen Kaffee / möchten / bestellen]', 'Write the sentence: He would like to order a coffee. (modal möchte, infinitive at the end)', NULL, 'Er möchte einen Kaffee bestellen.', '["Er möchte einen Kaffee bestellen.","Er möchte einen Kaffee bestellen"]'::jsonb, 'möchte is the conjugated modal in position 2; bestellen (infinitive) goes to the end.', 'möchte ist das konjugierte Modalverb auf Position 2; bestellen (Infinitiv) steht am Ende.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Er + möchte (pos 2) + einen Kaffee + bestellen (end, infinitive).', 'Satzklammer: Er + möchte (Pos 2) + einen Kaffee + bestellen (Ende, Infinitiv).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef3c3e7a-c001-5105-be64-7500ac2d9e29'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '238bd552-e9b6-56b5-841b-1d7a7d123af7'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / das Zimmer / sollen / aufräumen]', 'Write the sentence: We should tidy up the room. (modal sollen, separable infinitive at the end)', NULL, 'Wir sollen das Zimmer aufräumen.', '["Wir sollen das Zimmer aufräumen.","Wir sollen das Zimmer aufräumen"]'::jsonb, 'sollen is the conjugated modal in position 2; aufräumen (infinitive, prefix attached) goes to the end.', 'sollen ist das konjugierte Modalverb auf Position 2; aufräumen (Infinitiv, Präfix bleibt dran) steht am Ende.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Satzklammer: Wir + sollen (pos 2) + das Zimmer + aufräumen (end, infinitive).', 'Satzklammer: Wir + sollen (Pos 2) + das Zimmer + aufräumen (Ende, Infinitiv).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '238bd552-e9b6-56b5-841b-1d7a7d123af7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8b24d4df-fe92-51f3-bd3c-2e3f3293f2f2'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'fill_blank', '___ du am Samstag kommen? (können)', 'Can you come on Saturday? (modal question, du-form)', NULL, 'Kannst', '["Kannst"]'::jsonb, 'können conjugates to kannst for du and moves to position 1 in a yes/no question.', 'können wird für du zu kannst und steht in der Ja/Nein-Frage auf Position 1.', NULL, 22, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Yes/no question: Kannst (verb first) + du + am Samstag kommen.', 'Ja/Nein-Frage: Kannst (Verb zuerst) + du + am Samstag kommen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8b24d4df-fe92-51f3-bd3c-2e3f3293f2f2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '25d904ad-f85d-547d-b6c8-0b915a13cc76'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'fill_blank', 'Ich ___ jetzt nach Hause gehen. (müssen)', 'I have to go home now. (modal conjugation, ich-form)', NULL, 'muss', '["muss"]'::jsonb, 'müssen conjugates to muss for ich.', 'müssen wird für ich zu muss.', NULL, 23, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich muss + gehen (infinitive) at the end.', 'ich muss + gehen (Infinitiv) am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '25d904ad-f85d-547d-b6c8-0b915a13cc76'::uuid);

