SELECT '92d30d06-515f-598b-a32f-8a43e0a42696'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'fill_blank', 'Ihr ___ am Wochenende einkaufen. (wollen)', 'You (pl.) want to go shopping on the weekend. (modal conjugation, ihr-form)', NULL, 'wollt', '["wollt"]'::jsonb, 'wollen conjugates to wollt for ihr, different from the infinitive.', 'wollen wird für ihr zu wollt, anders als der Infinitiv.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr wollt + einkaufen (infinitive) at the end.', 'ihr wollt + einkaufen (Infinitiv) am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '92d30d06-515f-598b-a32f-8a43e0a42696'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '580c71bc-f6bf-5ecb-b131-8a0b5b46650d'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'fill_blank', '___ wir hier parken? (dürfen)', 'May we park here? (modal question, wir-form)', NULL, 'Dürfen', '["Dürfen"]'::jsonb, 'dürfen keeps the -en form for wir and moves to position 1 in a yes/no question.', 'dürfen behält für wir die Form -en und steht in der Ja/Nein-Frage auf Position 1.', NULL, 25, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Yes/no question: Dürfen (verb first) + wir + hier parken.', 'Ja/Nein-Frage: Dürfen (Verb zuerst) + wir + hier parken.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '580c71bc-f6bf-5ecb-b131-8a0b5b46650d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ffec17c9-0060-5e63-a64e-e7391e43c962'::uuid, '521fe67a-c23d-46f0-84ec-3207a2080a15'::uuid, 5, 'sentence_building', 'Schreib den Satz: [was / du / wollen / machen]', 'Write the sentence: What do you want to do? Start with ''was''. (modal W-question, Satzklammer)', NULL, 'Was willst du machen?', '["Was willst du machen?","Was willst du machen"]'::jsonb, 'The cue puts was first (the W-word); willst (modal) is position 2, du is position 3, machen (infinitive) is at the end.', 'Der Hinweis stellt was (W-Wort) an erste Stelle; willst (Modalverb) ist Position 2, du Position 3, machen (Infinitiv) am Ende.', NULL, 26, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'W-question Satzklammer: Was (pos 1) + willst (pos 2) + du (pos 3) + machen (end).', 'W-Fragen-Satzklammer: Was (Pos 1) + willst (Pos 2) + du (Pos 3) + machen (Ende).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ffec17c9-0060-5e63-a64e-e7391e43c962'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd58b99cd-91ae-543c-9b59-ccf080542e9f'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Ich habe ___ Bruder. (kein)', 'I have no brother. (kein + der Bruder, accusative)', NULL, 'keinen', '["keinen"]'::jsonb, 'Bruder is masculine, so kein becomes keinen in the accusative.', 'Bruder ist maskulin, deshalb wird kein zu keinen im Akkusativ.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative: einen → keinen. Der Bruder → keinen Bruder.', 'Maskulin, Akkusativ: einen → keinen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd58b99cd-91ae-543c-9b59-ccf080542e9f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e5ad8d92-8eb0-5b95-b134-6201df8b65ba'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Das Auto ist ___ neu.', 'The car is not new. (nicht + adjective)', NULL, 'nicht', '["nicht"]'::jsonb, 'nicht negates the adjective neu, not a noun.', 'nicht verneint das Adjektiv neu, kein Nomen.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'There is no ein/eine before neu, so use nicht, not kein.', 'Kein ein/eine vor neu, also nicht statt kein.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e5ad8d92-8eb0-5b95-b134-6201df8b65ba'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0b004f56-aa19-58e3-9d41-cfcfc82a238a'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Wir haben ___ Tisch.', 'We have no table. (kein + der Tisch, accusative)', NULL, 'keinen', '["keinen"]'::jsonb, 'Tisch is masculine, so kein takes the -en ending in the accusative.', 'Tisch ist maskulin, kein bekommt die Endung -en im Akkusativ.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative object → keinen Tisch.', 'Maskulines Akkusativobjekt → keinen Tisch.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0b004f56-aa19-58e3-9d41-cfcfc82a238a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4e28dae4-a90b-5aa1-8297-8c49ff40dacb'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Ich trinke ___ Kaffee.', 'I don''t drink coffee. (kein + der Kaffee, accusative)', NULL, 'keinen', '["keinen"]'::jsonb, 'Kaffee is masculine, so kein becomes keinen before it.', 'Kaffee ist maskulin, deshalb kein → keinen.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine noun as object → keinen Kaffee.', 'Maskulines Objekt → keinen Kaffee.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4e28dae4-a90b-5aa1-8297-8c49ff40dacb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7c0fc4b8-a8ae-5b4d-b8d3-a610b27329c2'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Er kommt heute ___ mit.', 'He is not coming along today. (nicht with separable verb mitkommen)', NULL, 'nicht', '["nicht"]'::jsonb, 'nicht stands right before the separable prefix mit at the end.', 'nicht steht direkt vor mit (Präfix am Satzende).', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mitkommen splits: kommt ... mit. nicht goes right before mit.', 'mitkommen trennt sich: kommt ... mit. nicht steht vor mit.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7c0fc4b8-a8ae-5b4d-b8d3-a610b27329c2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef1e9c4e-8bb7-5a26-9590-5255b9580b22'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Das Essen schmeckt ___ gut.', 'The food doesn''t taste good. (nicht + adjective)', NULL, 'nicht', '["nicht"]'::jsonb, 'nicht negates the adjective gut here, not a noun.', 'nicht verneint hier das Adjektiv gut, kein Nomen.', NULL, 14, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'No ein/eine before gut, so nicht is correct, not kein.', 'Kein ein/eine vor gut, also nicht, nicht kein.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef1e9c4e-8bb7-5a26-9590-5255b9580b22'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e947a074-3cc3-54eb-808b-92b8109a30f4'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Sie hat ___ Geschwister.', 'She has no siblings. (kein, plural noun)', NULL, 'keine', '["keine"]'::jsonb, 'Plural nouns always use keine, regardless of gender.', 'Pluralnomen nehmen immer keine, egal welches Geschlecht.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Geschwister is plural → keine, like die → keine.', 'Geschwister ist Plural → keine, wie die → keine.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e947a074-3cc3-54eb-808b-92b8109a30f4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3953e665-93f7-51a8-83ef-64a0d8455a23'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Ich bin heute ___ zu Hause.', 'I am not at home today. (nicht before a place)', NULL, 'nicht', '["nicht"]'::jsonb, 'nicht negates the place expression zu Hause.', 'nicht verneint die Ortsangabe zu Hause.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'zu Hause is a place, not a noun with ein/eine, so use nicht.', 'zu Hause ist eine Ortsangabe, kein ein/eine-Nomen, also nicht.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3953e665-93f7-51a8-83ef-64a0d8455a23'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0aae594f-f849-5da0-a289-2aafc08052ba'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / kein / Computer / haben]', 'Write the sentence: I have no computer. (kein + masculine noun — must inflect to keinen)', NULL, 'Ich habe keinen Computer.', '["Ich habe keinen Computer.","Ich habe keinen Computer"]'::jsonb, 'Computer is masculine, so the given kein must be inflected to keinen in the accusative.', 'Computer ist maskulin, deshalb muss das gegebene kein im Akkusativ zu keinen werden.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative object needs the -en ending: kein → keinen Computer.', 'Maskulines Akkusativobjekt braucht die Endung -en: kein → keinen Computer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0aae594f-f849-5da0-a289-2aafc08052ba'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e2bd9783-ab59-5017-87b9-74872bf836c4'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / keine / Zeit / haben]', 'Write the sentence: We have no time. (kein + feminine noun, wir-form of haben)', NULL, 'Wir haben keine Zeit.', '["Wir haben keine Zeit.","Wir haben keine Zeit"]'::jsonb, 'Zeit is feminine, so kein becomes keine.', 'Zeit ist feminin, deshalb wird kein zu keine.', NULL, 18, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine accusative → keine Zeit, same form as nominative.', 'Feminines Akkusativ → keine Zeit, gleich wie Nominativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e2bd9783-ab59-5017-87b9-74872bf836c4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1b0e08fd-2629-52c8-881a-287913fb41a7'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / das Auto / kaufen / nicht]', 'Write the sentence: We are not buying the car. (nicht after a definite direct object)', NULL, 'Wir kaufen das Auto nicht.', '["Wir kaufen das Auto nicht.","Wir kaufen das Auto nicht","Das Auto kaufen wir nicht.","Das Auto kaufen wir nicht"]'::jsonb, 'nicht negates the whole action and goes after the definite object das Auto, at the end.', 'Das bestimmte Objekt (das Auto) steht vor nicht; nicht bleibt am Satzende.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Definite object before nicht: Wir kaufen (pos 2) + das Auto + nicht (end). Fronting das Auto instead (Das Auto kaufen wir nicht.) is equally correct — nicht still closes the sentence.', 'Bestimmtes Objekt vor nicht: Wir kaufen (Pos 2) + das Auto + nicht (Ende). Auch mit das Auto zuerst (Das Auto kaufen wir nicht.) bleibt nicht am Satzende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1b0e08fd-2629-52c8-881a-287913fb41a7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bfcdead9-e332-5068-b7ab-dcbdb309c044'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Ich kenne hier ___ Leute.', 'I don''t know any people here. (kein + die Leute, plural, verb kennen)', NULL, 'keine', '["keine"]'::jsonb, 'Leute is plural, so kein becomes keine regardless of gender.', 'Leute ist Plural, deshalb wird kein zu keine, unabhängig vom Geschlecht.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural accusative negation: kein → keine Leute.', 'Plural-Akkusativ-Verneinung: kein → keine Leute.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bfcdead9-e332-5068-b7ab-dcbdb309c044'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '146c2939-7a76-5fae-9fcf-2101fbefd494'::uuid, '12f69c82-437c-454d-ba6f-4476351c4a69'::uuid, 5, 'fill_blank', 'Wir brauchen ___ Auto.', 'We don''t need a car. (kein + das Auto, accusative, verb brauchen)', NULL, 'kein', '["kein"]'::jsonb, 'Auto is neuter, so kein stays kein (no ending); brauchen takes an accusative object.', 'Auto ist Neutrum, deshalb bleibt kein kein (keine Endung); brauchen verlangt ein Akkusativobjekt.', NULL, 21, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Neuter accusative negation needs no ending: kein Auto.', 'Neutrale Akkusativ-Verneinung braucht keine Endung: kein Auto.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '146c2939-7a76-5fae-9fcf-2101fbefd494'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'aa5ff641-2750-582d-8ca4-7f89947b69ee'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', '___ Zug kommt pünktlich. (der Zug)', 'The train arrives on time. (nominative subject, definite article)', NULL, 'Der', '["Der"]'::jsonb, 'Der Zug is the subject (Wer kommt? Der Zug), so it stays nominative.', 'Der Zug ist das Subjekt (Wer kommt? Der Zug), deshalb bleibt es Nominativ.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subject of the sentence = nominative: der Zug, not den Zug.', 'Subjekt des Satzes = Nominativ: der Zug, nicht den Zug.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'aa5ff641-2750-582d-8ca4-7f89947b69ee'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b35716bf-8d8d-544d-a457-4cabf3181cd4'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', 'Heute arbeitet ___ Lehrer nicht. (der)', 'Today the teacher is not working. (nominative subject, unchanged article under inversion)', NULL, 'der', '["der"]'::jsonb, 'Lehrer is still the subject after inversion, so the article stays der, not den.', 'Lehrer bleibt auch nach der Inversion das Subjekt, deshalb bleibt der Artikel der, nicht den.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Inversion moves the verb, not the case: der Lehrer stays nominative after Heute arbeitet.', 'Inversion verschiebt das Verb, nicht den Fall: der Lehrer bleibt Nominativ nach Heute arbeitet.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b35716bf-8d8d-544d-a457-4cabf3181cd4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '934c861f-f2f3-54ca-8c0d-07db236c42bc'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', '___ Familie wohnt in Köln. (unser)', 'Our family lives in Cologne. (nominative subject, feminine possessive)', NULL, 'Unsere', '["Unsere"]'::jsonb, 'Familie is feminine, so the possessive unser takes the -e ending.', 'Familie ist feminin, deshalb bekommt unser die Endung -e.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine nominative subject: unsere Familie, like eine Familie.', 'Feminines Nominativsubjekt: unsere Familie, wie eine Familie.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '934c861f-f2f3-54ca-8c0d-07db236c42bc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '22a79ca8-efb9-5bfc-872d-b9f34af29c70'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', 'Sie bleibt ___ Freundin. (mein)', 'She remains my friend. (nominative predicate after bleiben, possessive)', NULL, 'meine', '["meine"]'::jsonb, 'bleiben also takes a nominative complement, like sein; Freundin is feminine, so mein becomes meine.', 'bleiben nimmt wie sein ein Nominativ-Prädikat; Freundin ist feminin, deshalb wird mein zu meine.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Complement after bleiben = nominative: meine Freundin, feminine -e ending.', 'Prädikat nach bleiben = Nominativ: meine Freundin, feminine -e-Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '22a79ca8-efb9-5bfc-872d-b9f34af29c70'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd08121ad-a928-55ee-b34e-a5aba9af8ad2'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', 'Wer kommt heute? — ___ kommen heute. (wir)', 'Who is coming today? We are coming today. (nominative subject pronoun)', NULL, 'Wir', '["Wir"]'::jsonb, 'wir is the nominative subject pronoun answering wer.', 'wir ist das Nominativ-Subjektpronomen als Antwort auf wer.', NULL, 20, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wer fragt nach dem Subjekt; die Antwort ist das Pronomen wir, Nominativ.', 'Wer asks for the subject; the answer is the pronoun wir, nominative.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd08121ad-a928-55ee-b34e-a5aba9af8ad2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd2d9655f-6089-5f12-a81b-aabc0ea911ae'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Lehrer / heute / krank / sein]', 'Write the sentence: The teacher is sick today. Start with ''der Lehrer''. (nominative subject, sein)', NULL, 'Der Lehrer ist heute krank.', '["Der Lehrer ist heute krank.","Der Lehrer ist heute krank","Heute ist der Lehrer krank.","Heute ist der Lehrer krank"]'::jsonb, 'The cue''s first element, der Lehrer, is position 1, so it stays nominative and ist follows.', 'Der erste Teil des Hinweises, der Lehrer, steht auf Position 1, bleibt Nominativ, dann ist.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subject-first (cue order): Der Lehrer (pos 1, nominative) + ist (pos 2) + heute krank. Fronting heute instead (Heute ist der Lehrer krank.) is equally correct German — der Lehrer stays nominative either way.', 'Subjekt zuerst (laut Hinweis): Der Lehrer (Pos 1, Nominativ) + ist (Pos 2) + heute krank. Auch mit heute zuerst (Heute ist der Lehrer krank.) bleibt der Lehrer Nominativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd2d9655f-6089-5f12-a81b-aabc0ea911ae'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '29315c4b-85f0-524f-b75f-60748230ed5e'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', 'Wer ist das? — Das ist ___ Kollege. (mein)', 'Who is that? That is my colleague. (nominative predicate after sein, possessive)', NULL, 'mein', '["mein"]'::jsonb, 'After sein, the noun stays nominative; masculine mein has no ending here.', 'Nach sein bleibt das Nomen Nominativ; maskulines mein hat hier keine Endung.', NULL, 22, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Predicate after sein = nominative: mein Kollege, not meinen Kollegen.', 'Prädikat nach sein = Nominativ: mein Kollege, nicht meinen Kollegen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '29315c4b-85f0-524f-b75f-60748230ed5e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '67ab5387-ed2c-529c-be72-ded3ff3a506c'::uuid, '0163af26-86f5-499e-b534-d4b77cc56510'::uuid, 5, 'fill_blank', '___ Freunde sind nett. (die)', 'The friends are nice. (nominative plural subject)', NULL, 'Die', '["Die"]'::jsonb, 'Freunde is the plural subject, so it uses the nominative plural article die.', 'Freunde ist das Pluralsubjekt, deshalb steht der Nominativ-Plural-Artikel die.', NULL, 23, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural nominative: die Freunde, same form as the accusative plural.', 'Nominativ Plural: die Freunde, gleiche Form wie Akkusativ Plural.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '67ab5387-ed2c-529c-be72-ded3ff3a506c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5cbcd867-a9ec-5efc-99fd-5592f796e587'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib die Zahl in Worten: 340 = ___', 'Write the number in words: 340 (hundreds)', NULL, 'dreihundertvierzig', '["dreihundertvierzig"]'::jsonb, '340 = drei + hundert + vierzig, written as one word.', '340 = drei + hundert + vierzig, als ein Wort geschrieben.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'drei-hundert-vierzig → dreihundertvierzig, no spaces.', 'drei-hundert-vierzig → dreihundertvierzig, ohne Leerzeichen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5cbcd867-a9ec-5efc-99fd-5592f796e587'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8c0a525e-1a01-5c88-ad2e-433221dc4e2e'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib die Zahl in Worten: 3000 = ___', 'Write the number in words: 3000 (thousands)', NULL, 'dreitausend', '["dreitausend"]'::jsonb, '3000 = drei + tausend, written as one word.', '3000 = drei + tausend, als ein Wort geschrieben.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'drei-tausend → dreitausend, like dreihundert for hundreds.', 'drei-tausend → dreitausend, wie dreihundert bei den Hundertern.', NULL
