INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd6c3655e-af71-5f4b-ba9e-aaa8f6cc8290'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib die Zahl in Worten: 2026 = ___', 'Write the number in words: 2026 (thousands + tens)', NULL, 'zweitausendsechsundzwanzig', '["zweitausendsechsundzwanzig"]'::jsonb, '2026 = zwei + tausend + sechsundzwanzig, all one word.', '2026 = zwei + tausend + sechsundzwanzig, alles ein Wort.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'zwei-tausend-sechsundzwanzig → zweitausendsechsundzwanzig.', 'zwei-tausend-sechsundzwanzig → zweitausendsechsundzwanzig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd6c3655e-af71-5f4b-ba9e-aaa8f6cc8290'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
