SELECT 'c0e3e3d1-f496-5721-9f77-1f7aa68e5f1a'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib den Preis in Worten: 0,99 € = ___', 'Write the price in words: 0.99 euros (cents only)', NULL, 'neunundneunzig Cent', '["neunundneunzig Cent"]'::jsonb, 'Under one euro, only the cents are named.', 'Ohne einen ganzen Euro nennt man nur die Cent.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, '0,99 € has no whole euro, so only Cent is said.', '0,99 € hat keinen ganzen Euro, deshalb nur Cent.', NULL
