SELECT '490e3196-419f-57fd-ad2d-1d07b898585c'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib den Preis in Worten: 15 € = ___', 'Write the price in words: 15 euros (whole euros only)', NULL, 'fünfzehn Euro', '["fünfzehn Euro"]'::jsonb, 'A whole-euro price just states the number plus Euro, no plural -s.', 'Ein glatter Euro-Preis nennt nur die Zahl plus Euro, kein Plural-s.', NULL, 14, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '15 € = fünfzehn Euro, not fünfzehn Euros.', '15 € = fünfzehn Euro, nicht fünfzehn Euros.', NULL
