SELECT '4870e180-1391-5ccd-9a30-79d9899f8f2b'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Das ist die ___ Straße links. (3.)', 'That is the third street on the left. (ordinal, feminine nominative)', NULL, 'dritte', '["dritte"]'::jsonb, '3. is irregular: dritte, not dreite.', '3. ist unregelmäßig: dritte, nicht dreite.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine nominative ordinal: die dritte Straße.', 'Feminines Nominativ-Ordinalzahl: die dritte Straße.', NULL
