SELECT 'ef8d932c-7251-50db-83e5-152d01584919'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Ich wohne im ___ Stock. (1.)', 'I live on the first floor. (ordinal, im + -en ending)', NULL, 'ersten', '["ersten"]'::jsonb, '1. is irregular: erste, and after im it takes the -en ending.', '1. ist unregelmäßig: erste, und nach im bekommt es die Endung -en.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'im + ersten Stock, like im vierten Stock.', 'im + ersten Stock, wie im vierten Stock.', NULL
