SELECT '8445b30d-d68a-540f-a6dc-b1c645c7fa44'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Das ist die ___ Tür links. (8.)', 'That is the eighth door on the left. (ordinal, feminine nominative)', NULL, 'achte', '["achte"]'::jsonb, '8. is irregular: achte, not achtte.', '8. ist unregelmäßig: achte, nicht achtte.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine nominative ordinal: die achte Tür.', 'Feminines Nominativ-Ordinalzahl: die achte Tür.', NULL
