SELECT '77a23cd0-dddf-5704-bd01-d105a130e676'::uuid, '951ce3b2-0cb0-40ea-90a2-2f665564b7de'::uuid, 5, 'fill_blank', 'Schreib die Telefonnummer in Worten: 07234 = ___', 'Write the phone number in words: 07234 (digit by digit)', NULL, 'null-sieben-zwei-drei-vier', '["null-sieben-zwei-drei-vier","null sieben zwei drei vier"]'::jsonb, 'Phone numbers are read one digit at a time.', 'Telefonnummern liest man Ziffer für Ziffer.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, '0-7-2-3-4 → null-sieben-zwei-drei-vier, digit by digit.', '0-7-2-3-4 → null-sieben-zwei-drei-vier, Ziffer für Ziffer.', NULL
