INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '18fdc9ae-c2b8-5aa4-83cf-c9e11fe8edf5'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / kaufen / ein Geschenk / für / meine Mutter]', 'Write the sentence: I am buying a gift for my mother. (für + accusative, feminine — no change)', NULL, 'Ich kaufe ein Geschenk für meine Mutter.', '["Ich kaufe ein Geschenk für meine Mutter.","Ich kaufe ein Geschenk für meine Mutter","Für meine Mutter kaufe ich ein Geschenk.","Für meine Mutter kaufe ich ein Geschenk"]'::jsonb, 'für always triggers accusative; Mutter is feminine, so meine stays meine (no change).', 'für verlangt immer Akkusativ; Mutter ist feminin, deshalb bleibt meine gleich (keine Änderung).', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'für + feminine accusative: meine Mutter, unlike masculine mein → meinen. Fronting für meine Mutter instead is equally correct German.', 'für + feminin Akkusativ: meine Mutter, anders als maskulin mein → meinen. Auch mit für meine Mutter zuerst ist der Satz richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '18fdc9ae-c2b8-5aa4-83cf-c9e11fe8edf5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b2466d45-634e-5d58-aa29-1031cc720c9a'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Ich habe eine Frage für ___ Lehrer. (ein Lehrer)', 'I have a question for a teacher. (für + accusative, indefinite article)', NULL, 'einen', '["einen"]'::jsonb, 'für always triggers accusative; Lehrer is masculine, so ein becomes einen.', 'für verlangt immer Akkusativ; Lehrer ist maskulin, deshalb wird ein zu einen.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'für + masculine accusative: ein → einen Lehrer.', 'für + maskulin Akkusativ: ein → einen Lehrer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b2466d45-634e-5d58-aa29-1031cc720c9a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd7cdfd44-16db-5115-a3e4-cf630d20760e'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Wir laufen um ___ Stuhl. (der Stuhl)', 'We walk around the chair. (um + accusative, definite article)', NULL, 'den', '["den"]'::jsonb, 'um always triggers accusative; Stuhl is masculine, so der becomes den.', 'um verlangt immer Akkusativ; Stuhl ist maskulin, deshalb wird der zu den.', NULL, 18, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'um + masculine accusative: der → den Stuhl.', 'um + maskulin Akkusativ: der → den Stuhl.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd7cdfd44-16db-5115-a3e4-cf630d20760e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '128dd4a9-0ece-5b7a-998a-b7d11dcc5e86'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Die Jungen laufen um ___ Baum. (ein Baum)', 'The boys run around a tree. (um + accusative, indefinite article)', NULL, 'einen', '["einen"]'::jsonb, 'um always triggers accusative; Baum is masculine, so ein becomes einen.', 'um verlangt immer Akkusativ; Baum ist maskulin, deshalb wird ein zu einen.', NULL, 19, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'um + masculine accusative: ein → einen Baum.', 'um + maskulin Akkusativ: ein → einen Baum.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '128dd4a9-0ece-5b7a-998a-b7d11dcc5e86'::uuid);

