SELECT 'ca49b948-8f00-500e-8a88-2f8c58ced76e'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Wir gehen durch ___ Supermarkt. (der Supermarkt)', 'We walk through the supermarket. (durch + accusative, definite article)', NULL, 'den', '["den"]'::jsonb, 'durch always triggers accusative; Supermarkt is masculine, so der becomes den.', 'durch verlangt immer Akkusativ; Supermarkt ist maskulin, deshalb wird der zu den.', NULL, 20, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'durch + masculine accusative: der → den Supermarkt.', 'durch + maskulin Akkusativ: der → den Supermarkt.', NULL
