SELECT 'b172e6a9-f11d-5ebe-aa19-363c1ccd785d'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Wir laufen um ___ Schule. (die Schule)', 'We walk around the school. (um + accusative, feminine — no change from nominative)', NULL, 'die', '["die"]'::jsonb, 'Schule is feminine, so the accusative article stays die, unlike masculine der → den.', 'Schule ist feminin, deshalb bleibt der Akkusativartikel die, anders als maskulin der → den.', NULL, 21, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only masculine changes after accusative prepositions; feminine die stays die.', 'Nur Maskulin ändert sich nach Akkusativ-Präpositionen; feminines die bleibt die.', NULL
