SELECT 'a3ae29b4-9f7c-5cd4-966f-64e1c584a25f'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Ich bin gegen ___ Plan. (der Plan)', 'I am against the plan. (gegen + accusative, definite article)', NULL, 'den', '["den"]'::jsonb, 'gegen always triggers accusative; Plan is masculine, so der becomes den.', 'gegen verlangt immer Akkusativ; Plan ist maskulin, deshalb wird der zu den.', NULL, 23, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'gegen + masculine accusative: der → den Plan.', 'gegen + maskulin Akkusativ: der → den Plan.', NULL
