SELECT '0d62a541-125d-54a5-9f64-40a249688b3a'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'fill_blank', 'Ich gehe nie ohne ___ Schlüssel. (mein)', 'I never leave without my key. (ohne + accusative, possessive)', NULL, 'meinen', '["meinen"]'::jsonb, 'ohne always triggers accusative; Schlüssel is masculine, so mein becomes meinen.', 'ohne verlangt immer Akkusativ; Schlüssel ist maskulin, deshalb wird mein zu meinen.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ohne + masculine accusative: mein → meinen Schlüssel.', 'ohne + maskulin Akkusativ: mein → meinen Schlüssel.', NULL
