INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '91763b6e-9511-54a0-b044-ff13b01990ac'::uuid, '84073ebe-6780-47c2-b6dd-6afa77f82bb0'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / fahren / nicht / ohne / mein Bruder]', 'Write the sentence: I am not driving without my brother. (mein must be inflected to meinen — ohne + accusative)', NULL, 'Ich fahre nicht ohne meinen Bruder.', '["Ich fahre nicht ohne meinen Bruder.","Ich fahre nicht ohne meinen Bruder","Ohne meinen Bruder fahre ich nicht.","Ohne meinen Bruder fahre ich nicht"]'::jsonb, 'ohne always triggers accusative; Bruder is masculine, so the given mein must become meinen.', 'ohne verlangt immer Akkusativ; Bruder ist maskulin, deshalb muss das gegebene mein zu meinen werden.', NULL, 25, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ohne + masculine accusative: mein → meinen Bruder; ich fahre (regular, no stem change). Fronting ohne meinen Bruder instead is equally correct German.', 'ohne + maskulin Akkusativ: mein → meinen Bruder; ich fahre (regelmäßig, kein Vokalwechsel). Auch mit ohne meinen Bruder zuerst ist der Satz richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '91763b6e-9511-54a0-b044-ff13b01990ac'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '758bcf05-88c8-5d4a-a97a-6e9e5ca1a5ef'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Der Supermarkt ist in der Stadt. Frage: ___ ist der Supermarkt?', 'Answer: The supermarket is in town. Produce the question word for location.', NULL, 'Wo', '["Wo"]'::jsonb, 'The answer names a place, so the question needs wo (where).', 'Die Antwort nennt einen Ort, deshalb braucht die Frage wo.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Der Supermarkt ist in der Stadt answers Wo?, so the question word is Wo.', 'Der Supermarkt ist in der Stadt antwortet auf Wo?, also ist das Fragewort Wo.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '758bcf05-88c8-5d4a-a97a-6e9e5ca1a5ef'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ae1873de-5a3e-5e6a-b1f3-26622fe99392'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Wir fahren nach Berlin. Frage: ___ fahrt ihr?', 'Answer: We are driving to Berlin. Produce the question word for direction.', NULL, 'Wohin', '["Wohin"]'::jsonb, 'The answer names a destination, so the question needs wohin (where to).', 'Die Antwort nennt ein Ziel, deshalb braucht die Frage wohin.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wir fahren nach Berlin answers Wohin?, so the question word is Wohin.', 'Wir fahren nach Berlin antwortet auf Wohin?, also ist das Fragewort Wohin.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ae1873de-5a3e-5e6a-b1f3-26622fe99392'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4d5d1c5f-350f-5c74-b05c-6e6c11741fe8'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Meine Schwester heißt Lena. Frage: ___ heißt deine Schwester?', 'Answer: My sister is called Lena. Produce the question word for a name.', NULL, 'Wie', '["Wie"]'::jsonb, 'The answer gives a name, so the question needs wie (how, i.e. what is she called).', 'Die Antwort nennt einen Namen, deshalb braucht die Frage wie.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Meine Schwester heißt Lena answers Wie heißt sie?, so the word is Wie.', 'Meine Schwester heißt Lena antwortet auf Wie heißt sie?, also ist das Wort Wie.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4d5d1c5f-350f-5c74-b05c-6e6c11741fe8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b69cdbfe-c42a-5a65-9c7a-fbd09021f4ea'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Das Buch kostet zehn Euro. Frage: ___ kostet das Buch?', 'Answer: The book costs ten euros. Produce the question word for a price (either wording works).', NULL, 'Wie viel', '["Wie viel","Was"]'::jsonb, 'The answer gives one price, so the question needs wie viel (how much) — or simply was, as in Was kostet das?', 'Die Antwort nennt einen Preis, deshalb braucht die Frage wie viel — oder einfach was, wie in Was kostet das?', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Das Buch kostet zehn Euro answers both Wie viel kostet es? and Was kostet es?, so either word is correct.', 'Das Buch kostet zehn Euro antwortet auf Wie viel kostet es? und auf Was kostet es?, beide Wörter sind richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b69cdbfe-c42a-5a65-9c7a-fbd09021f4ea'::uuid);

