SELECT 'cdde482c-b661-5154-b003-34055637cfb6'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Ich habe zwei Brüder. Frage: ___ Brüder hast du?', 'Answer: I have two brothers. Produce the question word for a countable amount.', NULL, 'Wie viele', '["Wie viele"]'::jsonb, 'Brüder is a countable plural noun, so the question needs wie viele (how many).', 'Brüder ist ein zählbares Pluralnomen, deshalb braucht die Frage wie viele.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Zwei Brüder is a count, so the question word is wie viele, not wie viel.', 'Zwei Brüder ist eine Anzahl, also ist das Fragewort wie viele, nicht wie viel.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cdde482c-b661-5154-b003-34055637cfb6'::uuid);

