SELECT 'a680863b-d8bf-5667-b260-ac22c6b3ca56'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Der Kurs beginnt um neun Uhr. Frage: ___ beginnt der Kurs?', 'Answer: The course starts at nine o''clock. Produce the question word for time (or the fuller time question).', NULL, 'Wann', '["Wann","Um wie viel Uhr"]'::jsonb, 'The answer names a time, so the question needs wann (when) — or the fuller um wie viel Uhr.', 'Die Antwort nennt eine Uhrzeit, deshalb braucht die Frage wann — oder ausführlicher um wie viel Uhr.', NULL, 14, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Um neun Uhr answers both Wann? and Um wie viel Uhr?, so either is correct.', 'Um neun Uhr antwortet auf Wann? und auf Um wie viel Uhr?, beides ist richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a680863b-d8bf-5667-b260-ac22c6b3ca56'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0160ba9f-5d71-5714-afa5-c71d909fe22f'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Ich spreche Deutsch und Englisch. Frage: ___ Sprachen sprichst du?', 'Answer: I speak German and English. Produce the question word that asks which languages, not how many.', NULL, 'Welche', '["Welche"]'::jsonb, 'The answer picks specific languages from a group, so the question needs welche (which), not wie viele (how many).', 'Die Antwort nennt bestimmte Sprachen aus einer Gruppe, deshalb braucht die Frage welche, nicht wie viele.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Naming specific languages answers Welche Sprachen?, not a count, so it is Welche.', 'Bestimmte Sprachen zu nennen antwortet auf Welche Sprachen?, keine Anzahl, also Welche.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0160ba9f-5d71-5714-afa5-c71d909fe22f'::uuid);

