SELECT '2662013f-bb4f-53f8-8fdc-606b5bc1841a'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'fill_blank', 'Antwort: Mein Bruder kommt heute. Frage: ___ kommt heute?', 'Answer: My brother is coming today. Produce the question word for a person.', NULL, 'Wer', '["Wer"]'::jsonb, 'The answer names who is coming, so the question needs wer (who).', 'Die Antwort nennt, wer kommt, deshalb braucht die Frage wer.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Mein Bruder kommt heute answers Wer kommt heute?, so the question word is Wer.', 'Mein Bruder kommt heute antwortet auf Wer kommt heute?, also ist das Fragewort Wer.', NULL
