INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '97cb2bd7-3f5d-586f-bee1-032808437aab'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wie viele / Kinder / du / haben]', 'Write the sentence: How many children do you have? Start with ''wie viele''. (W-word + verb + subject order)', NULL, 'Wie viele Kinder hast du?', '["Wie viele Kinder hast du?","Wie viele Kinder hast du"]'::jsonb, 'The cue puts wie viele Kinder first, so hast (verb) is position 2 and du follows.', 'Der Hinweis stellt wie viele Kinder an erste Stelle, deshalb ist hast (Verb) auf Position 2, dann du.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'W-question order: Wie viele Kinder (pos 1) + hast (pos 2) + du (pos 3).', 'W-Fragen-Struktur: Wie viele Kinder (Pos 1) + hast (Pos 2) + du (Pos 3).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '97cb2bd7-3f5d-586f-bee1-032808437aab'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'edce8810-334e-5234-b03b-a9a90e94cb21'::uuid, '8f070e1e-3dee-413b-b2cc-0e0eec40440c'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wann / ihr / ankommen]', 'Write the sentence: When do you (pl.) arrive? Start with ''wann''. (W-word + verb + subject order, separable verb ankommen)', NULL, 'Wann kommt ihr an?', '["Wann kommt ihr an?","Wann kommt ihr an"]'::jsonb, 'The cue puts wann first, so kommt (verb) is position 2 and ihr follows; an goes to the end.', 'Der Hinweis stellt wann an erste Stelle, deshalb ist kommt (Verb) auf Position 2, dann ihr; an steht am Ende.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'W-question order: Wann (pos 1) + kommt (pos 2) + ihr (pos 3) + an (end).', 'W-Fragen-Struktur: Wann (Pos 1) + kommt (Pos 2) + ihr (Pos 3) + an (Ende).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'edce8810-334e-5234-b03b-a9a90e94cb21'::uuid);


